text.p:

					Snapshot trace using IAR Embedded Workbench for ARM

					The IAR debugger can be configured to save the trace buffer to a host-side file, either manually or automatically, using a debugger macro. Follow these steps:




							Create a macro file in the project directory (e.g. "save_trace_buffer.mac") with the following contents:


__var start;
__var end;

save_trace_buffer()
{
start = __smessage "Memory:0x",RecorderDataPtr:%x;
end  =  __smessage "Memory:0x",(RecorderDataPtr + 1):%x;
__memorySave(start,end,"intel-extended", "$$PROJ_DIR$$\\trace.hex", 0);

return 0;
}






							Add the macro file under Options -> Debugger -> Use Macro File(s).



							When in a debug session, open View -> Macros -> Debugger Macros and check that "save_trace_buffer" is included.



							Now, to call the macro and thereby save the trace, you have three options:



									Manually: In the Debugger Macros view, right-click on you macro and select "Add to Quicklaunch window". Now you can save the trace by double-clicking on the blue "refresh" icon in the Quicklaunch window.



									On a breakpoint: Place a breakpoint on a suitable location in the code. Open it in the breakpoint editor and enter your macro name (e.g., "save_trace_buffer()") in the Action -> Expression field. The trace is now saved every time that breakpoint is hit.



									On every halt: To update the trace on every halt, rename the "save_trace_buffer" function to execUserExecutionStopped(). That is a special hook that is called every time the execution is halted. Note that this can slow down single-stepping if the buffer is large.

					You can automate this procedure and get a tool bar button for this command, as illustrated above. To do this, open the "Function Editor" (in "Debug" menu, enabled when debugging...) and add the below code:


FUNC void SavePercepioRecorderData(void)
{
printf("Saving Recorder Data in out.hex!\n");
exec("SAVE \"out.hex\"  RecorderDataPtr , (RecorderDataPtr + 1)");
}
DEFINE BUTTON "Save Recorder Data", "SavePercepioRecorderData()"

pre.code:
xTraceDependencyRegister("MyProject.elf", TRC_DEPENDENCY_TYPE_ELF);

xTracePrintCompactF("MyUserEventChannel", "Variable number of arguments: %d, %d", arg1, arg2);
xTracePrintCompactF0("MyUserEventChannel", "My message");
xTracePrintCompactF1("MyUserEventChannel", "One value: %d", arg1);
xTracePrintCompactF2("MyUserEventChannel", "Two values: %d, %d", arg1, arg2);
xTracePrintCompactF3("MyUserEventChannel", "Three values: %d, %d, %d", arg1, arg2, arg3);
xTracePrintCompactF4("MyUserEventChannel", "Four values: %d, %d, %d, %d", arg1, arg2, arg3, arg4);

code.pre:
/* Simple example*/

TraceStateMachineHandle_t myfsm;
TraceStateMachineStateHandle_t myfsm_stateA;
TraceStateMachineStateHandle_t myfsm_stateB;

...

/* Initialization */
xTraceStateMachineCreate("MyStateMachine", &myfsm);
xTraceStateMachineStateCreate(myfsm, "State A", &myfsm_stateA);
xTraceStateMachineStateCreate(myfsm, "State B", &myfsm_stateB);

...

/* When entering state A*/
xTraceStateMachineSetState(myfsm, myfsm_stateA);

/* When entering state B*/
xTraceStateMachineSetState(myfsm, myfsm_stateB);

/* Example using arrays */

#define MYFSM_NUMBER_OF_STATES (6)

const char * statenames[MYFSM_NUMBER_OF_STATES] = {
    "State A",
    "State B",
    "State C",
    "State D",
    "State E",
    "State F",
};

TraceStateMachineHandle_t myfsm;
TraceStateMachineStateHandle_t myfsm_state_handles[NUMBER_OF_STATES];

...

/* Initialization */
xTraceStateMachineCreate("MyStateMachine", &myfsm);

for (int i=0; i<NUMBER_OF_STATES; i++){
	xTraceStateMachineStateCreate(myfsm, statenames[i], &myfsm_state_handles[i]);
}

...

/* At each state transition */
xTraceStateMachineSetState(myfsm, myfsm_state_handles[newstate]);

/* Declarations needed for interval tracing: */
TraceIntervalChannelSetHandle_t myIntervalChannelSet;
TraceIntervalChannelHandle_t myIntervalChannel;
TraceIntervalInstanceHandle_t myIntervalInstance_A_to_B;

/* Initialization */
xTraceIntervalChannelSetCreate("My IntervalChannelSet", &myIntervalChannelSet);
xTraceIntervalChannelCreate("IntervalChannel_A_to_B", myIntervalChannelSet, &myIntervalChannel);

/* At the start of the interval. This sets myIntervalInstance_A_to_B. */
xTraceIntervalStart(myIntervalChannel, 0, &myIntervalInstance_A_to_B); // The 0 is uxValue. Sets the color.

/* At the end of the interval. Can be in a different task. */
xTraceIntervalStop(myIntervalChannel, myIntervalInstance_A_to_B);

TraceRunnableHandle_t xRunnableHandle;
xTraceRunnableRegister("MyRunnable_1", TRC_RUNNABLE_REGISTER_METHOD_USE_ENTRY_TABLE, &xRunnableHandle);

xTraceRunnableStart(xRunnableHandle);
/* code to trace */
xTraceRunnableStop();

#define FOO_RUNNABLE_0 0
#define FOO_RUNNABLE_1 1
#define FOO_RUNNABLE_2 2

#define BAR_RUNNABLE_0 0
#define BAR_RUNNABLE_1 1

TraceRunnableStaticSetHandle_t xRunnableSetFoo;
TraceRunnableStaticSetHandle_t xRunnableSetBar;

xTraceRunnableRegisterStaticSet("FOO", 1, 0, 0, 3, &xRunnableSetFoo);
xTraceRunnableRegisterStaticSet("BAR", 1, 0, 0, 2, &xRunnableSetBar);

xTraceRunnableStartStatic(xRunnableSetFoo, FOO_RUNNABLE_0);
xTraceRunnableStopStatic();

xTraceRunnableStartStatic(xRunnableSetFoo, FOO_RUNNABLE_1);
xTraceRunnableStopStatic();

xTraceRunnableStartStatic(xRunnableSetFoo, FOO_RUNNABLE_2);
xTraceRunnableStopStatic();

xTraceRunnableStartStatic(xRunnableSetBar, BAR_RUNNABLE_0);
xTraceRunnableStopStatic();

xTraceRunnableStartStatic(xRunnableSetBar, BAR_RUNNABLE_1);
xTraceRunnableStopStatic();
